<script>
 import {onMount} from 'svelte';import {createQuickSelection} from '../coverflow-selection';
 import {layout,coverflowMax,saveLayout} from '../layout.svelte';import ResizeHandle from './ResizeHandle.svelte';
 import {ChevronLeft,ChevronRight,Check,FolderOpen,Minus,SquareCheck,ChevronDown,ChevronUp} from 'lucide-svelte';
 import {studio,assets,current,select,toggle} from '../studio.svelte';
 let list=$derived(assets());let index=$derived(Math.max(0,list.findIndex(a=>a.id===studio.aid)));let accumulator=0;let hovered=false,root,spaceHeld=$state(false),selecting=$state(true),badgeVisible=$state(false),badgeSelecting=$state(true),badgeEpoch=$state(0);let badgeTimer;
 function modeNotice(value,checked){spaceHeld=value;selecting=checked;clearTimeout(badgeTimer);if(value){badgeSelecting=checked;badgeVisible=true;badgeEpoch++;}else if(badgeVisible)badgeTimer=setTimeout(()=>badgeVisible=false,600);}
 const quick=createQuickSelection({getIds:()=>list.map(a=>a.id),getCurrent:()=>studio.aid,isSelected:id=>studio.selected.includes(id),setSelected:(ids,checked)=>{studio.selected=checked?[...new Set([...studio.selected,...ids])]:studio.selected.filter(id=>!ids.includes(id));studio.batchScope='auto';},navigate:select,onHeld:modeNotice});
 function typing(){const el=document.activeElement;return !!el&&(el.isContentEditable||!!el.closest('input,textarea,select,[role=textbox]'));}
 function available(){return hovered&&!typing()&&!studio.busy&&!studio.modal&&!studio.confirm&&!layout.coverflowCollapsed&&studio.mode==='edit'&&studio.view==='canvas';}
 function release(){quick.release();accumulator=0;}
 function keyDown(e){
  if(e.code==='Escape'){release();return;}
  if(e.ctrlKey||e.altKey||e.metaKey||e.isComposing)return;
  if(quick.held&&(e.code==='ArrowLeft'||e.code==='ArrowRight')){
   if(!available()){release();return;}
   e.preventDefault();e.stopPropagation();
   quick.step(e.code==='ArrowLeft'?-1:1);return;
  }
  if(e.code!=='Space'||!available())return;
  e.preventDefault();e.stopPropagation();if(!e.repeat)quick.press();
 }
 function keyUp(e){if(e.code!=='Space'||!quick.held)return;e.preventDefault();e.stopPropagation();release();}
 onMount(()=>{window.addEventListener('keydown',keyDown,true);window.addEventListener('keyup',keyUp,true);window.addEventListener('blur',release);const hide=()=>{if(document.hidden)release();};document.addEventListener('visibilitychange',hide);return()=>{window.removeEventListener('keydown',keyDown,true);window.removeEventListener('keyup',keyUp,true);window.removeEventListener('blur',release);document.removeEventListener('visibilitychange',hide);release();clearTimeout(badgeTimer);};});
 $effect(()=>{studio.pid;if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed)release();});let selectedCount=$derived(list.filter(a=>studio.selected.includes(a.id)).length);let allSelected=$derived(list.length>0&&selectedCount===list.length);
 function selectAll(){if(studio.busy)return;const ids=list.map(a=>a.id);studio.selected=allSelected?studio.selected.filter(id=>!ids.includes(id)):[...new Set([...studio.selected,...ids])];studio.batchScope='auto';}
 function previous(){if(index>0)select(list[index-1].id);}function next(){if(index<list.length-1)select(list[index+1].id);}
 function wheel(e){if(studio.busy||studio.modal||studio.confirm||layout.coverflowCollapsed){release();return;}e.preventDefault();const delta=e.deltaY||e.deltaX;if(quick.held){if(!available()){release();return;}quick.wheel(delta*(e.deltaMode===1?16:e.deltaMode===2?240:1));return;}accumulator+=delta;if(accumulator>35){next();accumulator=0;}else if(accumulator< -35){previous();accumulator=0;}}
 let pointer=null,dragged=false;
 function dragStart(e){if(e.button!==0||studio.busy||e.target.closest('.cf-check,.cf-arrow'))return;pointer={id:e.pointerId,x:e.clientX,last:e.clientX};dragged=false;}
 function dragMove(e){if(!pointer||e.pointerId!==pointer.id)return;const dx=e.clientX-pointer.last;if(!dragged&&Math.abs(e.clientX-pointer.x)<7)return;dragged=true;e.currentTarget.setPointerCapture(e.pointerId);while(Math.abs(e.clientX-pointer.last)>=65){if(e.clientX<pointer.last)next();else previous();pointer.last+=e.clientX<pointer.last?-65:65;}e.preventDefault();}
 function dragEnd(){pointer=null;setTimeout(()=>dragged=false,0);}
 // Exact GVPAK STUDIO 2 geometry and timing, reimplemented as a Svelte component.
 function position(offset){const a=Math.abs(offset);const x=offset===0?0:Math.sign(offset)*(130+(a-1)*75);const y=offset===0?0:offset<0?44:-44;return `transform:translateX(${x}px) translateZ(${offset===0?60:-a*40}px) rotateY(${y}deg) scale(${offset===0?1.06:Math.max(.68,.95-a*.06)});--cf-wash:${Math.min(.7,a*.14)};z-index:${100-a};`;}
</script>
<section bind:this={root} class="cf-root" class:quick-selecting={spaceHeld} onpointerenter={e=>{hovered=e.pointerType!=='touch';}} onpointerleave={()=>{hovered=false;release();}} onpointercancel={()=>{hovered=false;release();}} class:collapsed={layout.coverflowCollapsed} aria-label="图片浏览" title="单击空格切换勾选；按住空格加滚轮或方向键连续勾选；按住鼠标左右拖动切图" style:--cf-height={`${Math.min(layout.coverflowHeight,coverflowMax())}px`} onwheel={wheel}>
 <ResizeHandle axis="height" bind:value={layout.coverflowHeight} min={100} max={coverflowMax()} label="图片浏览区高度" onstart={()=>layout.coverflowCollapsed=false} onfinish={saveLayout} reset={()=>{layout.coverflowHeight=144;layout.coverflowCollapsed=false;}}/>
 <div class="cf-header"><button class="cf-project" onclick={()=>studio.view='projects'}><FolderOpen size={13}/>{current()?.name||"项目"}</button><span class="cf-header-actions"><button class="cf-collapse" aria-label={layout.coverflowCollapsed?"展开图片浏览区":"收起图片浏览区"} aria-expanded={!layout.coverflowCollapsed} title={layout.coverflowCollapsed?"展开图片浏览区":"收起图片浏览区"} onclick={()=>{layout.coverflowCollapsed=!layout.coverflowCollapsed;saveLayout();}}>{#if layout.coverflowCollapsed}<ChevronUp size={14}/>{:else}<ChevronDown size={14}/>{/if}</button><button class="cf-select-all" class:active={allSelected} role="checkbox" aria-checked={allSelected?true:selectedCount>0?'mixed':false} aria-label={allSelected?"取消全部勾选":"勾选全部图片"} title={allSelected?"取消全选":selectedCount?"勾选其余图片":"全选"} disabled={!list.length||!!studio.busy} onclick={selectAll}>{#if allSelected}<SquareCheck size={13}/>{:else if selectedCount}<Minus size={13}/>{:else}<span class="select-all-square"></span>{/if}全选</button>{list.length} 张图片{#if studio.selected.length}<b>{studio.selected.length} 已勾选</b>{/if}</span></div>
 <div class="cf-stage" role="group" aria-label="拖动切换图片" onpointerdown={dragStart} onpointermove={dragMove} onpointerup={dragEnd} onpointercancel={dragEnd} onclickcapture={e=>{if(dragged){e.preventDefault();e.stopPropagation();}}}><button class="cf-arrow cf-prev" disabled={index<=0} onclick={previous} aria-label="上一张图片"><ChevronLeft size={18}/></button><div class="cf-stack">{#each list as a,i (a.id)}{#if Math.abs(i-index)<=7}<div class:cf-current={i===index} class="cf-card" data-side={i>index?'right':i<index?'left':'center'} style={position(i-index)} role="group" aria-label={a.name}><button class="cf-image-button" onclick={()=>select(a.id)} aria-label={`打开 ${a.name}`}><img draggable="false" src={studio.thumbs[a.id]} alt={a.name}/></button><button class="cf-check" class:checked={studio.selected.includes(a.id)} onclick={()=>toggle(a.id)} aria-label={`勾选 ${a.name}`} aria-pressed={studio.selected.includes(a.id)}>{#if studio.selected.includes(a.id)}<Check size={11}/>{/if}</button><span class="cf-caption">{a.name}</span></div>{/if}{/each}</div><button class="cf-arrow cf-next" disabled={index>=list.length-1} onclick={next} aria-label="下一张图片"><ChevronRight size={18}/></button></div>
 <div class="cf-footer">{#key badgeEpoch}{#if badgeVisible}<span class="cf-mode-chip" class:removing={!badgeSelecting} class:released={!spaceHeld} role="status" aria-live="polite">{#if badgeSelecting}<Check size={12}/>{:else}<Minus size={12}/>{/if}{badgeSelecting?"勾选":"取消勾选"}</span>{/if}{/key}<button onclick={previous} disabled={index<=0} aria-label="上一张图片"><ChevronLeft size={12}/></button><span><b>{String(list.length?index+1:0).padStart(3,'0')}</b><i>/</i>{String(list.length).padStart(3,'0')}</span><button onclick={next} disabled={index>=list.length-1} aria-label="下一张图片"><ChevronRight size={12}/></button></div>
</section>
